<?php
declare(strict_types=1);
namespace Sentinel\Tests\Unit\Services;
use PDO; use PHPUnit\Framework\TestCase; use Sentinel\Core\Config; use Sentinel\Core\Database; use Sentinel\Core\HttpException; use Sentinel\Core\RuntimeContext; use Sentinel\Repositories\AuditRepository; use Sentinel\Repositories\DeviceAssignmentRepository; use Sentinel\Services\AuditService; use Sentinel\Services\DeviceAssignmentManagementService;
final class DeviceAssignmentManagementServiceTest extends TestCase { private function service():DeviceAssignmentManagementService{$db=new Database(new Config(['database'=>[]]),static fn():PDO=>new PDO('sqlite::memory:',null,null,[PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]));foreach(['devices (device_id INTEGER,company_id INTEGER,deleted_at TEXT)','employees (employee_id INTEGER,company_id INTEGER)','employee_assignments (employee_assignment_id INTEGER,company_id INTEGER,employee_id INTEGER,deleted_at TEXT)','device_assignments (device_assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER,device_id INTEGER,employee_id INTEGER,employee_assignment_id INTEGER,starts_at TEXT,ends_at TEXT,assignment_status TEXT,assigned_by_user_id INTEGER,returned_at TEXT,notes TEXT,created_at TEXT,updated_at TEXT)','audit_logs (audit_log_id INTEGER PRIMARY KEY,company_id INTEGER,user_id INTEGER,entity_name TEXT,entity_id TEXT,action_name TEXT,action_status TEXT,ip_address TEXT,user_agent TEXT,old_values TEXT,new_values TEXT,metadata TEXT)']as$sql)$db->execute('CREATE TABLE '.$sql);$db->execute('INSERT INTO devices VALUES (1,101,NULL)');$db->execute('INSERT INTO employees VALUES (7,101),(8,202)');$db->execute('INSERT INTO employee_assignments VALUES (11,101,7,NULL)');$context=new RuntimeContext();$context->setTenantId(101);$context->setUser('7');return new DeviceAssignmentManagementService(new DeviceAssignmentRepository($db,$context),$context,new AuditService(new AuditRepository($db,$context),$context));} public function testActiveCustodyRequiresMatchingTenantEmployeeAndCanEnd():void{$service=$this->service();$assignment=$service->assignDevice('1',['employee_id'=>7,'employee_assignment_id'=>11,'starts_at'=>'2026-09-14 08:00:00','assignment_status'=>'ACTIVE']);try{$service->assignDevice('1',['employee_id'=>7,'starts_at'=>'2026-09-14 09:00:00','assignment_status'=>'ACTIVE']);self::fail();}catch(HttpException $e){self::assertSame(409,$e->statusCode());}$ended=$service->endAssignment((string)$assignment['device_assignment_id'],['ends_at'=>'2026-09-14 10:00:00']);self::assertSame('ENDED',$ended['assignment_status']);} }